func newOrderCharge() unsafe.Pointer { return unsafe.Pointer(new(order.OrderCharge)) }

func newNOrderCharge(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]order.OrderCharge, n)))
}

func ptrOrderCharge(p unsafe.Pointer, c int32) any {
	r := (*order.OrderCharge)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.OrderID))
	case 4:
		return &r.Description
	case 5:
		return &r.Amount
	case 6:
		return (*string)(unsafe.Pointer(&r.InvoiceID))
	case 7:
		return &r.InvoicedAt
	case 8:
		return &r.Version
	case 9:
		return &r.CreatedAt
	case 10:
		return &r.UpdatedAt
	}
	return nil
}

func valueOrderCharge(p unsafe.Pointer, c int32) any {
	r := (*order.OrderCharge)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.OrderID)
	case 4:
		return r.Description
	case 5:
		return r.Amount
	case 6:
		if r.InvoiceID == "" {
			return nil
		}
		return string(r.InvoiceID)
	case 7:
		if r.InvoicedAt == 0 {
			return nil
		}
		return r.InvoicedAt
	case 8:
		return r.Version
	case 9:
		return r.CreatedAt
	case 10:
		return r.UpdatedAt
	}
	return nil
}

func attachOrderCharge(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*order.OrderCharge)(p)
	switch rel {
	case 0:
		r.Order = (*order.Order)(child)
	case 1:
		r.Allocations = append(r.Allocations, (*shipment.ChargeAllocation)(child))
	}
}

func init() {
	ordersTable.Relations[0].Target = customerdb.CustomersSchema()
	ordersTable.Relations[1].Target = tenantdb.UsersSchema()
	ordersTable.Relations[2].Target = tenantdb.UsersSchema()
	ordersTable.Relations[3].Target = shipmentdb.ShipmentsSchema()
	ordersTable.Relations[4].Target = OrderChargesSchema()
	orderChargesTable.Relations[0].Target = OrdersSchema()
	orderChargesTable.Relations[1].Target = shipmentdb.ChargeAllocationsSchema()
}

